data.minimal_example:
StickyHeader(
  child: ListView.builder(
    itemCount: 100,
    itemBuilder: (context, index) {
      if (index % 3 == 0) {
        return StickyContainerWidget(
          index: index,
          child: Container(
            height: 50,
            child: Text('Header #$index'),
          ),
        );
      }
      return Container(height: 80);
    },
  ),
);
